using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

/// <summary>Tools available to the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns relevant snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
        try
        {
            // Use DuckDuckGo instant-answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _http.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract text
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for \"{query}\". Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings as you research.")]
    public static string TakeNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

// --- Main ---

Console.WriteLine("=== AI Research Agent ===\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.WriteLine("Set the OPENAI_API_KEY environment variable to run this agent.");
    Console.WriteLine("Example: export OPENAI_API_KEY=sk-...");
    return;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.TakeNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Breaking the topic into sub-questions
        2. Using the SearchWeb tool to find information
        3. Using the TakeNote tool to record key findings
        4. After gathering enough information, use GetNotes to review your findings
        5. Provide a final comprehensive summary to the user

        Be thorough — perform multiple searches to cover different aspects of the topic.
        Always take notes on important findings before moving to the next search.
        """)
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

messages.Add(new ChatMessage(ChatRole.User, $"Research the following topic and provide a summary: {topic}"));

Console.WriteLine($"\nResearching \"{topic}\"...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

