using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

/// <summary>Tools available to the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns relevant snippets.")]
    public static async Task<string> SearchWeb(string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
        try
        {
            // Use DuckDuckGo instant-answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _http.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract text
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for \"{query}\". Try rephrasing the query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings as you research.")]
    public static string TakeNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

// --- Main ---

Console.WriteLine("=== AI Research Agent ===\n");

